import React, { useEffect, useState, useRef } from "react";
import SockJS from "sockjs-client";
import { Client } from "@stomp/stompjs";
import { API_BASE } from "../config";

export default function LudoBoard({ sessionId, token, myGameId }) {
  const [boardState, setBoardState] = useState([]);
  const [currentPlayer, setCurrentPlayer] = useState(0);
  const [gameOver, setGameOver] = useState(false);
  const [playerProfiles, setPlayerProfiles] = useState({
    me: null,
    opponent: null
  });

  const stompClientRef = useRef(null);
  const opponentCacheRef = useRef(null); // opponent profile cache

  // Fetch profile by gameId
  const fetchProfile = async (gameId) => {
    try {
      const res = await fetch(`${API_BASE}/api/user/profile/${gameId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        return await res.json();
      }
    } catch (err) {
      console.error("Profile fetch failed:", err);
    }
    return null;
  };

  // Initial load: My profile + Opponent profile (once)
  const loadProfiles = async (state) => {
    // My profile
    if (!playerProfiles.me) {
      const meProfile = await fetchProfile(myGameId);
      setPlayerProfiles((prev) => ({ ...prev, me: meProfile }));
    }

    // Opponent profile (only once)
    if (state?.players && state.players.length === 2) {
      const opponentId = state.players.find((id) => id !== myGameId);
      if (opponentId && !opponentCacheRef.current) {
        const opponentProfile = await fetchProfile(opponentId);
        opponentCacheRef.current = opponentProfile; // save in cache
        setPlayerProfiles((prev) => ({ ...prev, opponent: opponentProfile }));
      }
    }
  };

  useEffect(() => {
    if (!token || !sessionId) return;

    const socket = new SockJS(`${API_BASE}/ludo-ws?token=${encodeURIComponent(token)}`);
    const stompClient = new Client({
      webSocketFactory: () => socket,
      reconnectDelay: 5000,
      onConnect: () => {
        stompClient.subscribe(`/topic/game/${sessionId}`, async (msg) => {
          const state = JSON.parse(msg.body);
          setBoardState(state.playerTokens || []);
          setCurrentPlayer(state.currentPlayer ?? 0);
          setGameOver(state.gameOver || false);

          // Load my & opponent profiles if needed
          await loadProfiles(state);
        });
      },
    });

    stompClient.activate();
    stompClientRef.current = stompClient;

    return () => {
      stompClient.deactivate();
    };
  }, [sessionId, token]);

  const rollDice = () => {
    if (stompClientRef.current) {
      stompClientRef.current.publish({
        destination: `/app/game/${sessionId}/roll`,
        body: JSON.stringify({ gameId: myGameId }),
      });
    }
  };

  return (
    <div>
      <div className="player-info">
        {playerProfiles.me && (
          <div>
            <img
              src={`${API_BASE}${playerProfiles.me.avatarUrl}`}
              alt="me"
              width={50}
              height={50}
            />
            <p>{playerProfiles.me.displayName}</p>
          </div>
        )}
        {playerProfiles.opponent && (
          <div>
            <img
              src={`${API_BASE}${playerProfiles.opponent.avatarUrl}`}
              alt="opponent"
              width={50}
              height={50}
            />
            <p>{playerProfiles.opponent.displayName}</p>
          </div>
        )}
      </div>

      <div className="board">{/* Render your board here */}</div>

      {!gameOver && (
        <button onClick={rollDice} disabled={currentPlayer !== myGameId}>
          Roll Dice
        </button>
      )}
    </div>
  );
}
